insert into public.asgc_content(kind,slug,title,status,data,sort_order) values('event','nigeria-gulf-cooperation-forum-2026','[Test] Nigeria–Gulf Cooperation Forum 2026','published','{"desc":"A high-level forum convening Nigerian government officials, Gulf Cooperation Council partners and business representatives to explore frameworks for enhanced trade, investment and diplomatic cooperation.","speakers":["Ambassador Ahmed Sule, Founder/CEO, ASGC","Senior representatives from Gulf Cooperation Council missions","Nigerian Ministry of Foreign Affairs officials","Private sector leaders from Nigeria and the Gulf"],"registration":true,"date":"15 Oct 2026","title":"Nigeria–Gulf Cooperation Forum 2026","location":"Transcorp Hilton, Abuja, Nigeria","type":"Forum","img":"https://images.unsplash.com/photo-1590274853856-f22d5ee3d228?w=700&h=400&fit=crop&auto=format","past":false,"test_data":true}',0) on conflict(kind,slug) do nothing;
